// NV-DXVK start: Preserve buffer contents in sections and cache only unlocked views.
template <class Platform> class SectionShadow {
public:
  struct Stats {
    uint64_t backingBytes = 0, backingCount = 0, mappedVaBytes = 0, mappedCount = 0;
    uint64_t idleBudgetBytes = 0, locks = 0, maps = 0, unmaps = 0;
    uint64_t mapFailures = 0, unmapFailures = 0;
  };

private:
  struct Cache {
    std::mutex mutex;
    SectionShadow *head = nullptr;
    SectionShadow *tail = nullptr;
    Stats stats;
  };
  static Cache &cache() {
    static Cache instance;
    return instance;
  }
  typename Platform::Handle m_section{};
  uint8_t *m_view = nullptr;
  size_t m_size = 0, m_cost = 0, m_va = 0, m_budget = 0;
  size_t m_locks = 0;
  SectionShadow *m_prev = nullptr;
  SectionShadow *m_next = nullptr;
  bool m_listed = false;

  void unlink(Cache &c) {
    if (!m_listed) {
      return;
    }
    if (m_prev) {
      m_prev->m_next = m_next;
    } else {
      c.head = m_next;
    }
    if (m_next) {
      m_next->m_prev = m_prev;
    } else {
      c.tail = m_prev;
    }
    m_prev = m_next = nullptr;
    m_listed = false;
    c.stats.idleBudgetBytes -= m_cost;
  }
  bool unmap(Cache &c) {
    if (!m_view) {
      return true;
    }
    if (!Platform::unmap(m_view)) {
      ++c.stats.unmapFailures;
      return false;
    }
    unlink(c);
    c.stats.mappedVaBytes -= m_va;
    --c.stats.mappedCount;
    ++c.stats.unmaps;
    m_view = nullptr;
    m_va = 0;
    return true;
  }
  static void trim(Cache &c, size_t budget) {
    while (c.stats.idleBudgetBytes > budget && c.tail) {
      if (!c.tail->unmap(c)) {
        break;
      }
    }
  }

public:
  SectionShadow(size_t bytes, size_t budget) : m_size(bytes), m_budget(budget) {
    const auto granularity = Platform::granularity();
    if (!bytes || bytes > (std::numeric_limits<size_t>::max)() - (granularity - 1)) {
      throw std::bad_alloc();
    }
    m_cost = (bytes + granularity - 1) / granularity * granularity;
    m_section = Platform::create(bytes);
    if (!m_section) {
      throw std::bad_alloc();
    }
    auto &c = cache();
    std::lock_guard<std::mutex> guard(c.mutex);
    c.stats.backingBytes += bytes;
    ++c.stats.backingCount;
  }
  ~SectionShadow() {
    auto &c = cache();
    std::lock_guard<std::mutex> guard(c.mutex);
    // Remove every intrusive reference even if the OS rejects an unmap. The
    // retained VA remains charged and the failure counter does not claim release.
    unmap(c);
    unlink(c);
    c.stats.locks -= m_locks;
    Platform::close(m_section);
    c.stats.backingBytes -= m_size;
    --c.stats.backingCount;
  }
  SectionShadow(const SectionShadow &) = delete;
  SectionShadow &operator=(const SectionShadow &) = delete;

  uint8_t *acquire() {
    auto &c = cache();
    std::lock_guard<std::mutex> guard(c.mutex);
    unlink(c);
    if (!m_view) {
      trim(c, m_cost >= m_budget ? 0 : m_budget - m_cost);
      m_view = static_cast<uint8_t *>(Platform::map(m_section, m_size));
      if (!m_view) {
        // Release idle cache before retrying an allocation under fragmented VA.
        trim(c, 0);
        m_view = static_cast<uint8_t *>(Platform::map(m_section, m_size));
      }
      if (!m_view) {
        ++c.stats.mapFailures;
        return nullptr;
      }
      m_va = Platform::mappedBytes(m_view, m_size);
      c.stats.mappedVaBytes += m_va;
      ++c.stats.mappedCount;
      ++c.stats.maps;
    }
    ++m_locks;
    ++c.stats.locks;
    return m_view;
  }
  void release() {
    auto &c = cache();
    std::lock_guard<std::mutex> guard(c.mutex);
    if (!m_locks) {
      return;
    }
    --c.stats.locks;
    if (--m_locks) {
      return;
    }
    m_next = c.head;
    if (c.head) {
      c.head->m_prev = this;
    } else {
      c.tail = this;
    }
    c.head = this;
    m_listed = true;
    c.stats.idleBudgetBytes += m_cost;
    trim(c, m_budget);
  }
  uint8_t *get() const { return m_view; }
  static Stats stats() {
    auto &c = cache();
    std::lock_guard<std::mutex> guard(c.mutex);
    return c.stats;
  }
};

#ifdef _WIN32
struct WindowsSectionPlatform {
  using Handle = HANDLE;
  static size_t granularity() {
    static const size_t value = [] {
      SYSTEM_INFO info{};
      GetSystemInfo(&info);
      return static_cast<size_t>(info.dwAllocationGranularity);
    }();
    return value;
  }
  static Handle create(size_t bytes) {
    return CreateFileMappingW(INVALID_HANDLE_VALUE, nullptr, PAGE_READWRITE, 0, static_cast<DWORD>(bytes),
                              nullptr);
  }
  static void *map(Handle section, size_t bytes) {
    return MapViewOfFile(section, FILE_MAP_ALL_ACCESS, 0, 0, bytes);
  }
  static bool unmap(void *view) { return UnmapViewOfFile(view) != FALSE; }
  static void close(Handle section) { CloseHandle(section); }
  static size_t mappedBytes(void *view, size_t bytes) {
    MEMORY_BASIC_INFORMATION info{};
    return VirtualQuery(view, &info, sizeof(info)) ? info.RegionSize : bytes;
  }
};
using MappedBufferShadow = SectionShadow<WindowsSectionPlatform>;
#endif
